import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Fused Linear + ReLU CUDA kernel
fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_linear_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int input_size,
    int output_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * output_size) {
        int b = idx / output_size;
        int o = idx % output_size;
        float sum = bias[o];
        for(int k = 0; k < input_size; ++k) {
            sum += input[b * input_size + k] * weight[o * input_size + k];
        }
        output[idx] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor fused_linear_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int batch_size = input.size(0);
    int input_size = input.size(1);
    int output_size = weight.size(0);

    auto output = torch::zeros({batch_size, output_size}, input.options());

    int total_elements = batch_size * output_size;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_linear_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        input_size,
        output_size
    );

    return output;
}
"""

cpp_wrapper = "torch::Tensor fused_linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

fused_linear_relu = load_inline(
    name='fused_linear_relu',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_kernel_code,
    functions=['fused_linear_relu_cuda'],
    verbose=True
)

class FusedLinearReLU(nn.Module):
    def __init__(self, input_size, output_size):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(output_size, input_size))
        self.bias = nn.Parameter(torch.Tensor(output_size))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_linear_relu.fused_linear_relu_cuda(x, self.weight, self.bias)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_layer_sizes, output_size):
        super(ModelNew, self).__init__()
        layers = []
        current_input_size = input_size

        for hidden_size in hidden_layer_sizes:
            layers.append(FusedLinearReLU(current_input_size, hidden_size))
            current_input_size = hidden_size

        layers.append(nn.Linear(current_input_size, output_size))
        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)
